const email = $input.item.json;
const rawBody = (email.body && email.body.content)
  ? email.body.content
  : (email.bodyPreview || '');
const cleanBody = rawBody.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

const payload = {
  contents: [
    {
      role: 'user',
      parts: [
        {
          text: 'Extract air freight shipment details from this rate inquiry email body. Return only the 3-letter IATA airport code for pol and pod fields (e.g. "LHR" not "London Heathrow"). If chargeableWeightKg is not explicitly stated in the email, return null for that field. If any other field is not present, return empty string for text or null for numbers.\n\nEmail body:\n\n' + cleanBody
        }
      ]
    }
  ],
  generationConfig: {
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'object',
      properties: {
        pol:                { type: 'string' },
        pod:                { type: 'string' },
        shipper:            { type: 'string' },
        cargoType:          { type: 'string' },
        pieces:             { type: 'string' },
        piecesCount:        { type: 'number' },
        dimensions:         { type: 'string' },
        dimL:               { type: 'number' },
        dimW:               { type: 'number' },
        dimH:               { type: 'number' },
        dimUnit:            { type: 'string' },
        grossWeightKg:      { type: 'number' },
        chargeableWeightKg: { type: 'number' }
      },
      required: [
        'pol', 'pod', 'shipper', 'cargoType',
        'pieces', 'piecesCount', 'dimensions',
        'dimL', 'dimW', 'dimH', 'dimUnit',
        'grossWeightKg'
      ]
    }
  }
};

return {
  json: {
    emailId: email.id,
    emailSubject: email.subject,
    geminiPayload: payload
  }
};

const geminiResponse = $input.item.json;
const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text;

let parsed = {};
let needsManualReview = false;

if (!rawText) {
  needsManualReview = true;
} else {
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    needsManualReview = true;
  }
}

// Extract just the IATA code (3 uppercase letters) from POD/POL
function iata(s) {
  const m = (s || '').match(/\b([A-Z]{3})\b/);
  return m ? m[1] : (s || '').toUpperCase().replace(/[^A-Z]/g, '').slice(0, 3);
}

const pod = iata(parsed.pod || '');
const pol = iata(parsed.pol || '');

if (!pod) needsManualReview = true;

// Use || null so Gemini returning 0 is treated as "not stated"
let chargeableWeightKg = parsed.chargeableWeightKg || null;
if (chargeableWeightKg === null) {
  const L = parsed.dimL, W = parsed.dimW, H = parsed.dimH;
  const unit = (parsed.dimUnit || '').toLowerCase().trim();
  const pieces = parsed.piecesCount || 1;
  const gw = parsed.grossWeightKg || 0;

  if (L && W && H) {
    const toIn = unit === 'cm' ? (v) => v / 2.54 : (v) => v;
    const vw = (toIn(L) * toIn(W) * toIn(H) * pieces) / 166 / 2.2046;
    chargeableWeightKg = Math.round(Math.max(vw, gw) * 100) / 100;
  } else {
    chargeableWeightKg = gw || '';
  }
}

const sourceEmail = $('Build Gemini Payload').item.json;

return {
  json: {
    messageId: sourceEmail.emailId,
    originalSubject: sourceEmail.emailSubject,
    pol,
    pod,
    shipper: parsed.shipper || 'UNKNOWN',
    cargoType: parsed.cargoType || '',
    pieces: parsed.pieces || '',
    dimensions: parsed.dimensions || '',
    grossWeightKg: parsed.grossWeightKg ?? '',
    chargeableWeightKg,
    needsManualReview,
  },
};

function pad2(n) { return String(n).padStart(2, '0'); }
function normalizeDate(raw) {
  if (!raw) return '';
  return new Date(raw).toISOString().slice(0, 10);
}

// Case-insensitive, whitespace-tolerant column value getter
function col(row, colName) {
  const target = colName.replace(/\s+/g, ' ').trim().toUpperCase();
  for (const [k, v] of Object.entries(row)) {
    if (k.replace(/\s+/g, ' ').trim().toUpperCase() === target) return (v == null ? '' : String(v));
  }
  return '';
}

const todayISO = $now.toFormat('yyyy-LL-dd');
const todayYYMMDD = $now.toFormat('yyLLdd');

const logRows = $('Read Quote Log').all().map(i => i.json);
const contacts = $('Read Airline Contacts').all().map(i => i.json);

// Find highest seq number already used today
let maxSeq = 0;
for (const row of logRows) {
  if (normalizeDate(col(row, 'DATE')) !== todayISO) continue;
  const match = /^AECQ(\d{6})(\d{2})$/.exec(col(row, 'QUOTE NUMBER'));
  if (match && match[1] === todayYYMMDD) {
    const seq = parseInt(match[2], 10);
    if (seq > maxSeq) maxSeq = seq;
  }
}

const result = [];
let emailOffset = 0;

for (const item of $input.all()) {
  const current = item.json;
  emailOffset++;
  const quoteNumber = `AECQ${todayYYMMDD}${pad2(maxSeq + emailOffset)}`;

  let airlineCodes = [];
  let fallbackReason = null;

  if (current.needsManualReview) {
    airlineCodes = ['UNASSIGNED'];
    fallbackReason = 'Could not extract POD automatically - flagged for manual review';
  } else {
    const matches = logRows.filter(
      r => col(r, 'DEST').trim().toUpperCase() === current.pod.trim().toUpperCase()
    );

    if (matches.length === 0) {
      airlineCodes = ['UNASSIGNED'];
      fallbackReason = `No airline history on file for POD "${current.pod}"`;
    } else {
      matches.sort((a, b) => new Date(normalizeDate(col(b, 'DATE'))) - new Date(normalizeDate(col(a, 'DATE'))));
      const mostRecentDate = normalizeDate(col(matches[0], 'DATE'));
      const mostRecentRows = matches.filter(r => normalizeDate(col(r, 'DATE')) === mostRecentDate);

      const codes = new Set();
      for (const row of mostRecentRows) {
        col(row, 'AIRLINE').split(',').forEach(code => {
          const trimmed = code.trim();
          if (trimmed) codes.add(trimmed);
        });
      }
      airlineCodes = Array.from(codes);
      if (airlineCodes.length === 0) {
        airlineCodes = ['UNASSIGNED'];
        fallbackReason = `No airline history on file for POD "${current.pod}"`;
      }
    }
  }

  const contactEmailMap = {};
  for (const code of airlineCodes) {
    const row = contacts.find(
      c => col(c, 'AIRLINE CODE').trim().toUpperCase() === code.trim().toUpperCase()
    );
    contactEmailMap[code] = row ? col(row, 'EMAIL ADDRESS') : '';
  }

  result.push({
    json: { ...current, quoteNumber, airlineCodes, fallbackReason, contactEmailMap }
  });
}
return result;

const result = [];
for (const item of $input.all()) {
  const current = item.json;
  const codes = (current.airlineCodes && current.airlineCodes.length > 0)
    ? current.airlineCodes
    : ['UNASSIGNED'];
  for (const code of codes) {
    const contactEmail = (current.contactEmailMap && current.contactEmailMap[code]) || '';
    result.push({
      json: { ...current, airlineCode: code || 'UNASSIGNED', contactEmail }
    });
  }
}
return result;

const current = $input.item.json;

const contactEmail = current.contactEmail || '';

let remarkText;
if (current.fallbackReason) {
  remarkText = current.fallbackReason;
} else if (!contactEmail) {
  remarkText = `No contact email on file for airline code "${current.airlineCode}"`;
} else {
  remarkText = '';
}

const isDG = /\bDG\b|dangerous/i.test(current.cargoType || '');
const cargoTag = isDG ? 'DG' : 'GENERAL CARGO';
const airlineTag = current.airlineCode || 'UNASSIGNED';

const subject = `[${airlineTag}] ${current.pol}-${current.pod || '?'} / RATE QUOTE / ${cargoTag} / ${current.quoteNumber}`;

const body = [
  'Hello team,',
  '',
  'Please check the below shipment and provide us with rate and flight frequency.',
  '',
  `* POL : ${current.pol}`,
  `* POD : ${current.pod}`,
  '* UNKNOWN SHIPPER',
  `* ${current.cargoType}`,
  `* TOTAL ${current.pieces}`,
  `* ${current.dimensions}`,
  `* TOTAL G.W ${current.grossWeightKg} KGS`,
  `* TOTAL C.W ${current.chargeableWeightKg} KGS`,
  '',
  'Thank you.',
].join('\n');

return {
  json: {
    // Nested so autoMapInputData ignores these when writing to Google Sheets
    _draft: {
      messageId: current.messageId,
      to: contactEmail,
      subject,
      body,
    },
    // Flat sheet column keys — exactly matching quote log headers
    DATE: $now.toFormat('yyyy-LL-dd'),
    'EMAIL SUBJECT': current.originalSubject || '',
    'QUOTE NUMBER': current.quoteNumber || '',
    'AGENT/CUSTOMER': '',
    AIRLINE: current.airlineCode !== 'UNASSIGNED' ? current.airlineCode : '',
    DEST: current.pod || '',
    'CW (KGS)': current.chargeableWeightKg != null ? String(current.chargeableWeightKg) : '',
    'SENT BY': '',
    STATUS: 'DRAFT',
    REMARK: remarkText,
  },
};
